// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'comms-dish',
  role: 'prop',
  reference: 'models and assets images/phase-4/comms-dish.png'
};

function build() {
  const root = createRoot('comms-dish');
  const m = styleMaterials();

  // -------------------------------------------------------------------------
  // 1. PEDESTAL BASE (Ground Y = 0 to 0.44)
  // -------------------------------------------------------------------------
  const baseRot = [0, 22.5, 0]; // Aligns flat face perpendicular to +X

  // Bottom tier: wide octagonal plinth
  createPart('BaseBottom', cylinderGeo(1.05, 1.08, 0.14, 8), m.panelGray, { position: [0, 0.07, 0], rotation: baseRot, parent: root });
  createPart('BaseBottomChamfer', cylinderGeo(0.95, 1.05, 0.06, 8), m.panel, { position: [0, 0.17, 0], rotation: baseRot, parent: root });

  // Front maintenance hatch plate on +X face of lower base
  createPart('BaseHatchRecess', cylinderGeo(0.08, 0.08, 0.52, 4), m.trim, { position: [0.96, 0.09, 0], rotation: [0, 0, 90], scale: [0.35, 1, 0.75], parent: root });
  createPart('BaseHatchPlate', cylinderGeo(0.065, 0.065, 0.46, 4), m.panelGray, { position: [0.97, 0.09, 0], rotation: [0, 0, 90], scale: [0.30, 1, 0.70], parent: root });
  createPart('BaseHatchBevel', cylinderGeo(0.015, 0.015, 0.38, 4), m.trim, { position: [0.99, 0.09, 0], rotation: [90, 0, 0], parent: root });

  // Middle tier: stepped collar
  createPart('BaseMid', cylinderGeo(0.84, 0.86, 0.12, 8), m.panelGray, { position: [0, 0.26, 0], rotation: baseRot, parent: root });
  createPart('BaseMidChamfer', cylinderGeo(0.76, 0.84, 0.05, 8), m.panel, { position: [0, 0.345, 0], rotation: baseRot, parent: root });

  // Top collar tier
  createPart('BaseTopCollar', cylinderGeo(0.64, 0.66, 0.06, 8), m.trim, { position: [0, 0.40, 0], rotation: baseRot, parent: root });
  createPart('BaseTopRing', cylinderGeo(0.56, 0.58, 0.04, 16), m.panelGray, { position: [0, 0.45, 0], parent: root });

  // -------------------------------------------------------------------------
  // 2. PEDESTAL LEGS & ARCHED STANCHION (Y = 0.46 to 0.96)
  // -------------------------------------------------------------------------
  // 4 chunky angled buttress legs forming the sturdy open pedestal
  const legs = [
    { name: 'Leg_FL', px: 0.22, pz: 0.25, rx: -9, rz: -11 },
    { name: 'Leg_FR', px: 0.22, pz: -0.25, rx: -9, rz: 11 },
    { name: 'Leg_BL', px: -0.22, pz: 0.25, rx: 9, rz: -11 },
    { name: 'Leg_BR', px: -0.22, pz: -0.25, rx: 9, rz: 11 }
  ];

  for (const l of legs) {
    createPart(l.name, cylinderGeo(0.13, 0.18, 0.46, 6), m.panelGray, {
      position: [l.px, 0.69, l.pz],
      rotation: [l.rx, 0, l.rz],
      parent: root
    });
    // Foot pads at base of legs
    createPart(l.name + '_Foot', cylinderGeo(0.16, 0.20, 0.08, 6), m.panel, {
      position: [l.px * 1.15, 0.49, l.pz * 1.15],
      parent: root
    });
  }

  // Horizontal crossbeams creating the open archway
  createPart('ArchCrossbeamFront', cylinderGeo(0.09, 0.09, 0.46, 4), m.panelGray, { position: [0.20, 0.84, 0], rotation: [90, 0, 0], scale: [1, 1.3, 1], parent: root });
  createPart('ArchCrossbeamBack', cylinderGeo(0.09, 0.09, 0.46, 4), m.panelGray, { position: [-0.20, 0.84, 0], rotation: [90, 0, 0], scale: [1, 1.3, 1], parent: root });

  // Stanchion top platform
  createPart('StanchionTopPlate', cylinderGeo(0.40, 0.44, 0.08, 8), m.panelGray, { position: [0, 0.92, 0], rotation: baseRot, parent: root });
  createPart('StanchionTopChamfer', cylinderGeo(0.34, 0.40, 0.04, 8), m.panel, { position: [0, 0.98, 0], rotation: baseRot, parent: root });

  // -------------------------------------------------------------------------
  // 3. SWIVEL TURRET & YOKE CRADLE (Y = 1.00 to 1.70)
  // -------------------------------------------------------------------------
  createPart('TurretPost', cylinderGeo(0.20, 0.22, 0.14, 16), m.trim, { position: [0, 1.06, 0], parent: root });
  createPart('TurretBearingRing', cylinderGeo(0.26, 0.26, 0.06, 16), m.panel, { position: [0, 1.15, 0], parent: root });

  // Yoke lower horizontal crossbeam
  createPart('YokeCrossbeam', cylinderGeo(0.15, 0.15, 0.98, 6), m.panelGray, {
    position: [0, 1.23, 0],
    rotation: [90, 0, 0],
    scale: [1, 1.4, 1],
    parent: root
  });
  createPart('YokeCrossbeamCenter', cylinderGeo(0.22, 0.22, 0.34, 8), m.panel, {
    position: [0, 1.23, 0],
    rotation: [0, 22.5, 0],
    parent: root
  });

  // Left & Right Chunky Yoke Fork Arms
  createPart('YokeArm_L_Lower', cylinderGeo(0.13, 0.15, 0.36, 6), m.panelGray, {
    position: [0, 1.38, -0.44],
    rotation: [16, 0, 0],
    scale: [1.2, 1, 1],
    parent: root
  });
  createPart('YokeArm_L_Upper', cylinderGeo(0.14, 0.14, 0.32, 6), m.panelGray, {
    position: [0, 1.62, -0.52],
    scale: [1.2, 1, 1],
    parent: root
  });

  createPart('YokeArm_R_Lower', cylinderGeo(0.13, 0.15, 0.36, 6), m.panelGray, {
    position: [0, 1.38, 0.44],
    rotation: [-16, 0, 0],
    scale: [1.2, 1, 1],
    parent: root
  });
  createPart('YokeArm_R_Upper', cylinderGeo(0.14, 0.14, 0.32, 6), m.panelGray, {
    position: [0, 1.62, 0.52],
    scale: [1.2, 1, 1],
    parent: root
  });

  // Pivot hubs on outer sides of yoke arms
  const armZ = 0.52;
  for (const zSide of [-armZ, armZ]) {
    const s = Math.sign(zSide);
    createPart('PivotBoss_' + (s > 0 ? 'R' : 'L'), cylinderGeo(0.15, 0.15, 0.08, 12), m.panel, {
      position: [0, 1.68, zSide],
      rotation: [90, 0, 0],
      parent: root
    });
    createPart('PivotBolt_' + (s > 0 ? 'R' : 'L'), cylinderGeo(0.10, 0.10, 0.05, 8), m.trim, {
      position: [0, 1.68, zSide + s * 0.05],
      rotation: [90, 0, 0],
      parent: root
    });
    createPart('PivotCap_' + (s > 0 ? 'R' : 'L'), cylinderGeo(0.05, 0.05, 0.02, 6), m.panel, {
      position: [0, 1.68, zSide + s * 0.08],
      rotation: [90, 0, 0],
      parent: root
    });
  }

  // Horizontal pivot axle connecting between arms
  createPart('PivotAxle', cylinderGeo(0.08, 0.08, 0.94, 12), m.trim, {
    position: [0, 1.68, 0],
    rotation: [90, 0, 0],
    parent: root
  });

  // -------------------------------------------------------------------------
  // 4. DISH PIVOT & MOUNTING GIMBAL (Pivot at [0, 1.68, 0], tilted +32 deg up)
  // Required semantic node: "dish" (allows the game to rotate the dish)
  // -------------------------------------------------------------------------
  const dish = createPivot('dish', [0, 1.68, 0], root);
  dish.rotation.z = 32 * Math.PI / 180; // +32 degrees tilt upward towards the sky

  // Gearbox housing behind the pivot
  createPart('GimbalGearbox', cylinderGeo(0.24, 0.24, 0.38, 8), m.panelGray, {
    position: [-0.15, 0, 0],
    rotation: [0, 0, 90],
    scale: [1, 1, 0.85],
    parent: dish
  });
  createPart('GimbalCollar', cylinderGeo(0.28, 0.25, 0.12, 12), m.trim, {
    position: [-0.04, 0, 0],
    rotation: [0, 0, 90],
    parent: dish
  });

  // Rear dish mounting flange connecting gearbox to rear of dish (fully recessed behind dish)
  createPart('DishBackMountRing', cylinderGeo(0.32, 0.26, 0.12, 12), m.panel, {
    position: [-0.02, 0, 0],
    rotation: [0, 0, -90],
    parent: dish
  });

  // -------------------------------------------------------------------------
  // 5. REFLECTOR DISH & FACETED ORANGE RIM (16 segments)
  // -------------------------------------------------------------------------
  const SEGS = 16;

  // Custom Faceted White Reflector Dish Face
  function buildDishFace() {
    const geom = new THREE.BufferGeometry();
    const pos = [];
    const norm = [];

    const rings = [
      { r: 0.34, x: 0.10 }, // inner rim meeting hub
      { r: 0.80, x: 0.23 }, // mid panel crease
      { r: 1.20, x: 0.39 }  // outer edge meeting orange rim
    ];

    function addQuad(p0, p1, p2, p3) {
      const v0 = new THREE.Vector3(...p0);
      const v1 = new THREE.Vector3(...p1);
      const v2 = new THREE.Vector3(...p2);
      const v3 = new THREE.Vector3(...p3);

      const n1 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v1, v0),
        new THREE.Vector3().subVectors(v2, v0)
      ).normalize();

      const n2 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v2, v0),
        new THREE.Vector3().subVectors(v3, v0)
      ).normalize();

      pos.push(...p0, ...p1, ...p2);
      norm.push(n1.x, n1.y, n1.z, n1.x, n1.y, n1.z, n1.x, n1.y, n1.z);

      pos.push(...p0, ...p2, ...p3);
      norm.push(n2.x, n2.y, n2.z, n2.x, n2.y, n2.z, n2.x, n2.y, n2.z);
    }

    for (let i = 0; i < SEGS; i++) {
      const a0 = (i / SEGS) * Math.PI * 2;
      const a1 = ((i + 1) / SEGS) * Math.PI * 2;

      const c0 = Math.cos(a0), s0 = Math.sin(a0);
      const c1 = Math.cos(a1), s1 = Math.sin(a1);

      // Inner ring quad
      const p00 = [rings[0].x, rings[0].r * c0, rings[0].r * s0];
      const p10 = [rings[1].x, rings[1].r * c0, rings[1].r * s0];
      const p11 = [rings[1].x, rings[1].r * c1, rings[1].r * s1];
      const p01 = [rings[0].x, rings[0].r * c1, rings[0].r * s1];
      addQuad(p00, p10, p11, p01);

      // Outer ring quad
      const p20 = [rings[2].x, rings[2].r * c0, rings[2].r * s0];
      const p21 = [rings[2].x, rings[2].r * c1, rings[2].r * s1];
      addQuad(p10, p20, p21, p11);
    }

    geom.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geom.setAttribute('normal', new THREE.Float32BufferAttribute(norm, 3));
    return geom;
  }

  createPart('ReflectorFacetedPanels', buildDishFace(), m.panel, { parent: dish });

  // Custom Rear Dish Shell (Keeps the back enclosed and behind the white face)
  function buildDishBack() {
    const geom = new THREE.BufferGeometry();
    const pos = [];
    const norm = [];

    const rings = [
      { r: 0.44, x: 0.05 }, // rear hub collar
      { r: 0.82, x: 0.14 }, // mid rear shell
      { r: 1.20, x: 0.28 }  // meeting rear rim
    ];

    function addQuad(p0, p1, p2, p3) {
      const v0 = new THREE.Vector3(...p0);
      const v1 = new THREE.Vector3(...p1);
      const v2 = new THREE.Vector3(...p2);
      const v3 = new THREE.Vector3(...p3);

      const n1 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v1, v0),
        new THREE.Vector3().subVectors(v2, v0)
      ).normalize();

      const n2 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v2, v0),
        new THREE.Vector3().subVectors(v3, v0)
      ).normalize();

      pos.push(...p0, ...p1, ...p2);
      norm.push(n1.x, n1.y, n1.z, n1.x, n1.y, n1.z, n1.x, n1.y, n1.z);

      pos.push(...p0, ...p2, ...p3);
      norm.push(n2.x, n2.y, n2.z, n2.x, n2.y, n2.z, n2.x, n2.y, n2.z);
    }

    for (let i = 0; i < SEGS; i++) {
      const a0 = (i / SEGS) * Math.PI * 2;
      const a1 = ((i + 1) / SEGS) * Math.PI * 2;

      const c0 = Math.cos(a0), s0 = Math.sin(a0);
      const c1 = Math.cos(a1), s1 = Math.sin(a1);

      // Winding facing backwards (-X)
      const p00 = [rings[0].x, rings[0].r * c0, rings[0].r * s0];
      const p10 = [rings[1].x, rings[1].r * c0, rings[1].r * s0];
      const p11 = [rings[1].x, rings[1].r * c1, rings[1].r * s1];
      const p01 = [rings[0].x, rings[0].r * c1, rings[0].r * s1];
      addQuad(p00, p01, p11, p10);

      const p20 = [rings[2].x, rings[2].r * c0, rings[2].r * s0];
      const p21 = [rings[2].x, rings[2].r * c1, rings[2].r * s1];
      addQuad(p10, p11, p21, p20);
    }

    geom.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geom.setAttribute('normal', new THREE.Float32BufferAttribute(norm, 3));
    return geom;
  }

  createPart('DishRearShell', buildDishBack(), m.panelGray, { parent: dish });

  // Custom Faceted Bold Orange Outer Rim
  function buildOrangeRim() {
    const geom = new THREE.BufferGeometry();
    const pos = [];
    const norm = [];

    function addQuad(p0, p1, p2, p3) {
      const v0 = new THREE.Vector3(...p0);
      const v1 = new THREE.Vector3(...p1);
      const v2 = new THREE.Vector3(...p2);
      const v3 = new THREE.Vector3(...p3);

      const n1 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v1, v0),
        new THREE.Vector3().subVectors(v2, v0)
      ).normalize();

      const n2 = new THREE.Vector3().crossVectors(
        new THREE.Vector3().subVectors(v2, v0),
        new THREE.Vector3().subVectors(v3, v0)
      ).normalize();

      pos.push(...p0, ...p1, ...p2);
      norm.push(n1.x, n1.y, n1.z, n1.x, n1.y, n1.z, n1.x, n1.y, n1.z);

      pos.push(...p0, ...p2, ...p3);
      norm.push(n2.x, n2.y, n2.z, n2.x, n2.y, n2.z, n2.x, n2.y, n2.z);
    }

    for (let i = 0; i < SEGS; i++) {
      const a0 = (i / SEGS) * Math.PI * 2;
      const a1 = ((i + 1) / SEGS) * Math.PI * 2;

      const c0 = Math.cos(a0), s0 = Math.sin(a0);
      const c1 = Math.cos(a1), s1 = Math.sin(a1);

      // Rim cross section profile:
      const q0_0 = [0.39, 1.19 * c0, 1.19 * s0];
      const q0_1 = [0.39, 1.19 * c1, 1.19 * s1];

      const q1_0 = [0.42, 1.35 * c0, 1.35 * s0];
      const q1_1 = [0.42, 1.35 * c1, 1.35 * s1];

      const q2_0 = [0.29, 1.35 * c0, 1.35 * s0];
      const q2_1 = [0.29, 1.35 * c1, 1.35 * s1];

      const q3_0 = [0.27, 1.19 * c0, 1.19 * s0];
      const q3_1 = [0.27, 1.19 * c1, 1.19 * s1];

      // Front chamfer face
      addQuad(q0_0, q1_0, q1_1, q0_1);
      // Outer rim band
      addQuad(q1_0, q2_0, q2_1, q1_1);
      // Rear rim face
      addQuad(q2_0, q3_0, q3_1, q2_1);
    }

    geom.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geom.setAttribute('normal', new THREE.Float32BufferAttribute(norm, 3));
    return geom;
  }

  createPart('OrangeRim', buildOrangeRim(), m.accent, { parent: dish });

  // -------------------------------------------------------------------------
  // 6. DISH CENTER HUB & FEED HORN BOOM
  // -------------------------------------------------------------------------
  createPart('CenterHubBase', cylinderGeo(0.38, 0.40, 0.08, 16), m.panel, { position: [0.12, 0, 0], rotation: [0, 0, 90], parent: dish });
  createPart('CenterHubCollar', cylinderGeo(0.30, 0.32, 0.08, 16), m.panel, { position: [0.18, 0, 0], rotation: [0, 0, 90], parent: dish });
  createPart('CenterHubCap', cylinderGeo(0.22, 0.24, 0.04, 16), m.panel, { position: [0.23, 0, 0], rotation: [0, 0, 90], parent: dish });

  // Two angled support struts forming the V-shaped feed horn boom
  const strutLen = 0.86;
  createPart('FeedStrut_Top', cylinderGeo(0.05, 0.065, strutLen, 6), m.panel, {
    position: [0.55, 0.09, 0],
    rotation: [0, 0, -68],
    scale: [1, 1, 0.75],
    parent: dish
  });
  createPart('FeedStrut_Bottom', cylinderGeo(0.05, 0.065, strutLen, 6), m.panel, {
    position: [0.55, -0.09, 0],
    rotation: [0, 0, -112],
    scale: [1, 1, 0.75],
    parent: dish
  });

  // Feed Horn Assembly at focal point (X ~ 0.94 along dish axis)
  const feedX = 0.94;
  createPart('FeedHornMount', cylinderGeo(0.14, 0.16, 0.11, 8), m.panel, { position: [feedX, 0, 0], rotation: [0, 0, 90], parent: dish });
  createPart('FeedHornCollar', cylinderGeo(0.09, 0.10, 0.07, 12), m.trim, { position: [feedX + 0.08, 0, 0], rotation: [0, 0, 90], parent: dish });
  createPart('FeedHornSub', cylinderGeo(0.12, 0.09, 0.06, 8), m.panel, { position: [feedX + 0.14, 0, 0], rotation: [0, 0, 90], parent: dish });

  // Glowing Cyan Transceiver Gem / Lens at apex
  createPart('FeedSensorGem', cylinderGeo(0.07, 0.09, 0.08, 8), m.glowCool, { position: [feedX + 0.20, 0, 0], rotation: [0, 0, 90], parent: dish });
  createPart('FeedSensorTip', cylinderGeo(0.04, 0.07, 0.04, 8), m.glowCool, { position: [feedX + 0.25, 0, 0], rotation: [0, 0, 90], parent: dish });

  // Floating Station View info anchor
  createPivot('info_anchor', [0, 3.2, 0], root);

  defineBudget({ triangles: BUDGETS['medium-prop'] }, root);
  return root;
}
